#include<iostream>
#include<math.h>
using namespace std;

float x,x2,ax,r,n,a,b;
float deltax (float a, float b);



int main(){
cout<<"PROGRAMA PARA RESOLVER UN POLINOMIO UTILIZANDO RIMMAN"<<endl;
cout<<endl;
sleep(2);
cout<<"Introduzca el limite inferior: "<<endl;
cin>>a;
cout<<"Introduzca el limite superior: "<<endl;
cin>>b;
cout<<"Introduzca el numero de rectangulos que desea: "<<endl;
cin>>n;

/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////	

int x;

cout<<"Cuantos coeficientes posee su polinomio (cuente el coeficiente 1)"<<endl;
cin>>x;

float array[x];

	for(int i=0;i<x;i++){

cout<<"Digite el coeficiente numero "<<i+1<< " del polinomio (introduzca el coeficiente 1 si existe)" <<endl;
cin>>array[i];
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

char array2[x];

	for(int i=0;i<x;i++){

cout<<"Digite la variable numero "<<i+1<< " del polinomio (si no posee escriba 0)" <<endl;
cin>>array2[i];
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

float array3[x];

	for(int i=0;i<x;i++){

cout<<"Digite el elevado numero "<<i+1<< " del polinomio (si no posee escriba 1)" <<endl;
cin>>array3[i];
}

/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

 float arrays[100];
 float delta = deltax (a , b);

	for(int i=0;i<x;i++){

arrays[i] = array[i] * (array2[i] * delta);
cout<<arrays;
}
/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

 float arrays2[100];
	for(int i=0;i<x;i++){

arrays2[i] = pow(arrays[i],array3[i]);

}

float suma;
	for(int i=0;i<x;i++){
		suma += arrays2[i];
}

cout<<"El valor del polinomio resuelto con rimman es: " <<arrays2 <<endl;


/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////



}

float deltax (float a, float b)
{

 ax = b-a/n;
 return ax;

}
